def _sap_erp_data_source_field_from_nested(
    nested: SapErpDataSourceFieldNested,
) -> SapErpDataSourceField:
    """Convert nested format to flat SapErpDataSourceField."""
    attrs = (
        nested.attributes
        if nested.attributes is not UNSET
        else SapErpDataSourceFieldAttributes()
    )
    # Merge relationships from all three buckets
    merged_rels = merge_relationships(
        nested.relationship_attributes,
        nested.append_relationship_attributes,
        nested.remove_relationship_attributes,
        _SAP_ERP_DATA_SOURCE_FIELD_REL_FIELDS,
        SapErpDataSourceFieldRelationshipAttributes,
    )
    # Build kwargs so a field carried by both the top level and the merged
    # relationships (e.g. `meanings`) is passed once, with the relationship
    # value winning — otherwise the constructor gets a duplicate keyword.
    kwargs = {
        "guid": nested.guid,
        "type_name": nested.type_name,
        "status": nested.status,
        "version": nested.version,
        "create_time": nested.create_time,
        "update_time": nested.update_time,
        "created_by": nested.created_by,
        "updated_by": nested.updated_by,
        "classifications": nested.classifications,
        "classification_names": nested.classification_names,
        "meanings": nested.meanings,
        "labels": nested.labels,
        "business_attributes": nested.business_attributes,
        "custom_attributes": nested.custom_attributes,
        "pending_tasks": nested.pending_tasks,
        "proxy": nested.proxy,
        "is_incomplete": nested.is_incomplete,
        "provenance_type": nested.provenance_type,
        "home_id": nested.home_id,
        "delete_handler": nested.delete_handler,
        "depth": nested.depth,
        "immediate_upstream": nested.immediate_upstream,
        "immediate_downstream": nested.immediate_downstream,
    }
    kwargs.update(_extract_sap_erp_data_source_field_attrs(attrs))
    kwargs.update(merged_rels)
    return SapErpDataSourceField(**kwargs)


def _sap_erp_data_source_field_to_nested_bytes(
    sap_erp_data_source_field: SapErpDataSourceField, serde: Serde
) -> bytes:
    """Convert flat SapErpDataSourceField to nested JSON bytes."""
    return serde.encode(_sap_erp_data_source_field_to_nested(sap_erp_data_source_field))


def _sap_erp_data_source_field_from_nested_bytes(
    data: bytes, serde: Serde
) -> SapErpDataSourceField:
    """Convert nested JSON bytes to flat SapErpDataSourceField."""
    nested = serde.decode(data, SapErpDataSourceFieldNested)
    return _sap_erp_data_source_field_from_nested(nested)


